import{_ as l,W as o,s as u,u as d,ah as i,I as n,w as s,Z as p,A as e}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const C=JSON.parse('{"title":"如何在 Ubuntu 中安装具体指定的软件包版本 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中安装具体指定的软件包版本 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中安装具体指定的软件包版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中安装具体指定的软件包版本 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220518 Install Specific Package Version With Apt Command in Ubuntu","title":"如何在 Ubuntu 中安装具体指定的软件包版本","tag":"202206"},"relativePath":"202206/20220518 Install Specific Package Version With Apt Command in Ubuntu.md","filePath":"[post].md"}'),r={name:"202206/20220518 Install Specific Package Version With Apt Command in Ubuntu.md"};function b(c,a,g,h,m,v){const t=o("Link");return d(),u("div",null,[a[25]||(a[25]=i('<h1 id="如何在-ubuntu-中安装具体指定的软件包版本" tabindex="-1">如何在 Ubuntu 中安装具体指定的软件包版本 <a class="header-anchor" href="#如何在-ubuntu-中安装具体指定的软件包版本" aria-label="Permalink to 如何在 Ubuntu 中安装具体指定的软件包版本">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/26/145335zcrpducpup4p2ugy.jpg" alt=""></p><p>在 Ubuntu 中想安装一个软件包的一个特别指定的版本？你可以通过下面的方式来轻松地完成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install package_name=package_version</span></span></code></pre></div><p>你如何知道某个软件包有哪些可用的版本？可以使用这个命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt list --all-versions package_name</span></span></code></pre></div><p>在下面的屏幕截屏中，你可以看到，我有两个可用的 VLC 版本，我使用命令来安装较旧的版本：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/install-specific-versions-apt-ubuntu.png" alt="install specific versions apt ubuntu"></p><p>听起来像一个简单的任务，对吧？但是事情并非看起来那么简单。这里有一些不确定是否会出现，但是可能会涉及的东西。</p><p>这篇教程将涵盖使用 <code>apt</code> 或 <code>apt-get</code> 命令来安装一个具体指定的程序的版本的所有的重要的方面。</p><h3 id="安装一个具体指定版本的程序需要知道的事" tabindex="-1">安装一个具体指定版本的程序需要知道的事 <a class="header-anchor" href="#安装一个具体指定版本的程序需要知道的事" aria-label="Permalink to 安装一个具体指定版本的程序需要知道的事">​</a></h3><p>在基于 Ubuntu 和 Debian 发行版中，你需要知道一些关于 APT 和存储库是如何工作的知识。</p><h4 id="同一个软件包源没有较旧的版本" tabindex="-1">同一个软件包源没有较旧的版本 <a class="header-anchor" href="#同一个软件包源没有较旧的版本" aria-label="Permalink to 同一个软件包源没有较旧的版本">​</a></h4><p>Ubuntu 在其存储库中不保留较旧版本的软件包。在特殊的情况下，你可以暂时性地看到多个版本。例如，你运行 APT 更新（但不升级）时，可能会有一个可用的新版本。在 APT 缓存中，你可以看到同一个软件包的两个版本。但是，一旦软件包被升级到了新的版本，较旧版本的软件包将从 <strong>APT 缓存</strong> 和存储库中移除。</p><h4 id="使用多个软件包源来使用不同的版本" tabindex="-1">使用多个软件包源来使用不同的版本 <a class="header-anchor" href="#使用多个软件包源来使用不同的版本" aria-label="Permalink to 使用多个软件包源来使用不同的版本">​</a></h4>',15)),n("p",null,[a[1]||(a[1]=s("为获取同一个的软件包的多个版本，你必须得添加多个软件包源。例如，VLC 是版本 3.x 系列。添加 ")),p(t,{href:"https://launchpad.net/~videolan/+archive/ubuntu/master-daily"},{default:e(()=>a[0]||(a[0]=[s("VLC 每日构建 PPA")])),_:1}),a[2]||(a[2]=s(" 将会提供（不稳定的）版本 4.x 系列。"))]),a[26]||(a[26]=n("p",null,[s("同样，"),n("strong",null,"你可以下载不同版本的 DEB 文件，并安装它"),s("。")],-1)),a[27]||(a[27]=n("h4",{id:"较高版本编号的版本通常有优先权",tabindex:"-1"},[s("较高版本编号的版本通常有优先权 "),n("a",{class:"header-anchor",href:"#较高版本编号的版本通常有优先权","aria-label":"Permalink to 较高版本编号的版本通常有优先权"},"​")],-1)),a[28]||(a[28]=n("p",null,"如果你有来自多个软件包源的相同名称的软件，默认情况下，Ubuntu 将安装可用的最高版本编号的版本。",-1)),a[29]||(a[29]=n("p",null,"在前面的示例中，如果我安装 VLC ，那么它将会安装 4.x 系列的版本，而不是 3.x 系列的版本。",-1)),a[30]||(a[30]=n("h4",{id:"较旧版本将升级到可用的较新版本",tabindex:"-1"},[s("较旧版本将升级到可用的较新版本 "),n("a",{class:"header-anchor",href:"#较旧版本将升级到可用的较新版本","aria-label":"Permalink to 较旧版本将升级到可用的较新版本"},"​")],-1)),n("p",null,[a[4]||(a[4]=s("这是另外一个可能存在的问题。即使你安装较旧版本的软件包，它也会升级到较新的版本（如果存在可用的较新版本）。你必须 ")),p(t,{href:"https://itsfoss.com/prevent-package-update-ubuntu/"},{default:e(()=>a[3]||(a[3]=[s("保留该软件包来防止其升级")])),_:1}),a[5]||(a[5]=s(" 。"))]),a[31]||(a[31]=i(`<h4 id="依赖关系也需要安装" tabindex="-1">依赖关系也需要安装 <a class="header-anchor" href="#依赖关系也需要安装" aria-label="Permalink to 依赖关系也需要安装">​</a></h4><p>如果软件包有依赖关系，你也需要安装必要的依赖关系软件包。</p><p>现在，你已经知道一些可能存在的问题，让我们看看如何解决它们。</p><h3 id="安装一个软件包的具体指定版本" tabindex="-1">安装一个软件包的具体指定版本 <a class="header-anchor" href="#安装一个软件包的具体指定版本" aria-label="Permalink to 安装一个软件包的具体指定版本">​</a></h3><p>在这篇教程中，我将以 VLC 为例。在 Ubuntu 的存储库中可获得 VLC 版本。我添加了每日构建 PPA ，它将向我提供 VLC 的 4.0 版本的候选版本。</p><p>如你所见，在现在的系统中，我有两个可用的 VLC 版本：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/install-specific-versions-apt-ubuntu.png" alt="install specific versions apt ubuntu"></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~$ apt list -a vlc</span></span>
<span class="line"><span>Listing... Done</span></span>
<span class="line"><span>vlc/jammy 4.0.0~rc1~~git20220516+r92284+296~ubuntu22.04.1 amd64</span></span>
<span class="line"><span>vlc/jammy 3.0.16-1build7 amd64</span></span>
<span class="line"><span>vlc/jammy 3.0.16-1build7 i386</span></span></code></pre></div><p>因为较高版本编号版本有优先权，使用 <code>apt install vlc</code> 命令将会导致安装 VLC 的 4.0 版本。但是，因为这篇教程的缘由，我想安装较旧的版本 3.0.16 。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install vlc=3.0.16-1build7</span></span></code></pre></div>`,10)),n("p",null,[a[8]||(a[8]=s("但是，这里会有这样的事。VLC 软件包有一些依赖关系，并且这些依赖关系也需要具体指定的版本。因此，在 Ubuntu 为其尝试安装最新的版本时，你将会遇到经典的 ")),n("ruby",null,[p(t,{href:"https://itsfoss.com/held-broken-packages-error/"},{default:e(()=>a[6]||(a[6]=[s("你已保留残缺软件包")])),_:1}),a[7]||(a[7]=n("rt",null,"you have held broken packages",-1))]),a[9]||(a[9]=s(" 错误。"))]),a[32]||(a[32]=i(`<p><img src="https://itsfoss.com/wp-content/uploads/2022/05/problem-installing-specific-version-apt-ubuntu-800x365.png" alt="problem installing specific version apt ubuntu"></p><p>为修复这个错误，你需要为其提供它所投诉的所有依赖关系的软件包的具体指定版本。因此，该命令会变成这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install vlc=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-bin=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-base=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-qt=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-video-output=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-l10n=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-access-extra=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-notify=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-samba=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-skins2=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-video-splitter=3.0.16-1build7 \\</span></span>
<span class="line"><span>		 vlc-plugin-visualization=3.0.16-1build7</span></span></code></pre></div><p>说明一下，每行结尾处的 <code>\\</code> 只是用来将多行命令来写入同一个命令的一种方式。</p><p><strong>它有作用吗？在很多情况下，它是有作用的。</strong> 但是，我选择了一个复杂的 VLC 示例，它有很多依赖关系。甚至这些所涉及的依赖关系也依赖于其它的软件包。所以，它就变得令人难以处理。</p><p>一种替代的方法是在安装时指定软件包源。</p><h4 id="替代方式-指定存储库" tabindex="-1">替代方式，指定存储库 <a class="header-anchor" href="#替代方式-指定存储库" aria-label="Permalink to 替代方式，指定存储库">​</a></h4><p>你已经添加多个软件包源，因此，你应该对这些软件包的来源有一些了解。</p><p>使用下面的命令来搜索存储库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt-cache policy | less</span></span></code></pre></div><p>注意存储库名称后面的行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>500 http://security.ubuntu.com/ubuntu jammy-security/multiverse i386 Packages</span></span>
<span class="line"><span>     release v=22.04,o=Ubuntu,a=jammy-security,n=jammy,l=Ubuntu,c=multiverse,b=i386</span></span>
<span class="line"><span>     origin security.ubuntu.com</span></span></code></pre></div><p>你可以具体指定 <code>o</code>、<code>l</code>、<code>a</code> 等参数。</p><p>在我原来的示例中，我想安装来自 Ubuntu 存储库的 VLC（获取版本 3.16），而不是安装来 PPA 的版本（它将向我提供版本 4）。</p><p>因此，下面的命令将安装 VLC 版本 3.16 及其所有的依赖关系：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install -t &quot;o=ubuntu&quot; vlc</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/install-from-repository-source-800x578.png" alt="install from repository source"></p><p>看起来令人满意？但是，当你必须更新系统时，问题就来了。它接下来会控诉找不到指定的软件包版本。</p><p><strong>还能做什么？</strong></p><p>为安装较旧的软件包版本，从你的系统中移除较新版本的软件包源（如果可能的话）。它将有助于逃脱这些依赖关系地狱。</p><p>如果不能这么做，检查你是否可以从其它一些软件包的打包格式来获取，像 Snap、Flatpak、AppImage 等等。事实上，Snap 和 Flatpak 也允许你从可用的版本中选择和安装。因为这些应用程序是沙盒模式的，所以它很容易管理不同版本的依赖关系。</p><h4 id="保留软件包-防止升级" tabindex="-1">保留软件包，防止升级 <a class="header-anchor" href="#保留软件包-防止升级" aria-label="Permalink to 保留软件包，防止升级">​</a></h4><p>如果你完成安装一个指定的程序版本，你可能想避免意外地升级到较新的版本。实现这一点并不太复杂。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-mark hold package_name</span></span></code></pre></div><p>你可以免除保留软件包，以便它能稍后升级：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-mark unhold package_name</span></span></code></pre></div><p>注意，软件包的依赖关系不会自动地保留。它们需要单独地指明。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to 结论">​</a></h3><p>如你所见，安装选定软件包版本有一定之规。只有当软件包有依赖关系时，那么事情就会变得复杂，然后，你就会进入依赖关系地狱。</p><p>我希望你在这篇教程中学到一些新的东西。如果你有问题或建议来改善它，请在评论区告诉我。</p><hr>`,31)),n("p",null,[a[11]||(a[11]=s("via: ")),p(t,{href:"https://itsfoss.com/apt-install-specific-version-2/"},{default:e(()=>a[10]||(a[10]=[s("https://itsfoss.com/apt-install-specific-version-2/")])),_:1})]),n("p",null,[a[16]||(a[16]=s("作者：")),p(t,{href:"https://itsfoss.com/author/abhishek/"},{default:e(()=>a[12]||(a[12]=[s("Abhishek Prakash")])),_:1}),a[17]||(a[17]=s(" 选题：")),p(t,{href:"https://github.com/lkxed"},{default:e(()=>a[13]||(a[13]=[s("lkxed")])),_:1}),a[18]||(a[18]=s(" 译者：")),p(t,{href:"https://github.com/robsean"},{default:e(()=>a[14]||(a[14]=[s("robsean")])),_:1}),a[19]||(a[19]=s(" 校对：")),p(t,{href:"https://github.com/wxy"},{default:e(()=>a[15]||(a[15]=[s("wxy")])),_:1})]),n("p",null,[a[22]||(a[22]=s("本文由 ")),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>a[20]||(a[20]=[s("LCTT")])),_:1}),a[23]||(a[23]=s(" 原创编译，")),p(t,{href:"https://linux.cn/"},{default:e(()=>a[21]||(a[21]=[s("Linux中国")])),_:1}),a[24]||(a[24]=s(" 荣誉推出"))])])}const x=l(r,[["render",b]]);export{C as __pageData,x as default};
